import{V as e,et as t,mt as n,tt as r}from"./chunks/framework.DPTLmtS5.js";import"./chunks/assets.nkraVhM_.js";var i=JSON.parse(`{"title":"簡介","description":"","frontmatter":{},"headers":[],"relativePath":"zh-TW/guide/introduction.md","filePath":"zh-TW/guide/introduction.md","lastUpdated":1793173149000}`),a={name:`zh-TW/guide/introduction.md`};function o(e,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[r(`<h1 id="簡介" tabindex="-1">簡介 <a class="header-anchor" href="#簡介" aria-label="Permalink to “簡介”">​</a></h1><h2 id="關於數獨" tabindex="-1">關於數獨 <a class="header-anchor" href="#關於數獨" aria-label="Permalink to “關於數獨”">​</a></h2><p><strong>Sudoku — 經典數字謎題，完美呈現。</strong></p><p><img src="/screenshot-ipad-main.png" alt="Sudoku 在 iPad 上執行"></p><p>重新發現你熱愛的經典邏輯謎題，如今針對現代裝置重新琢磨：流暢的操作、漂亮的主題，以及百玩不膩的耐玩度。無論你是第一次接觸，還是經驗豐富的老手，這正是你期待已久的數獨體驗。</p><h2 id="核心功能" tabindex="-1">核心功能 <a class="header-anchor" href="#核心功能" aria-label="Permalink to “核心功能”">​</a></h2><h3 id="🔢-原汁原味的玩法" tabindex="-1">🔢 <strong>原汁原味的玩法</strong> <a class="header-anchor" href="#🔢-原汁原味的玩法" aria-label="Permalink to “🔢 原汁原味的玩法”">​</a></h3><p>忠實遵循經典規則——填滿 9×9 的方格，讓每一列、每一欄與每個 3×3 區塊都恰好包含 1 到 9 各一次。點一下即可填入數字，用鉛筆筆記記下候選數，讓邏輯帶你找出答案。</p><h3 id="🎯-5-種難度等級" tabindex="-1">🎯 <strong>5 種難度等級</strong> <a class="header-anchor" href="#🎯-5-種難度等級" aria-label="Permalink to “🎯 5 種難度等級”">​</a></h3><p>五種精心調校的難度，差別在於已知格的數量：</p><table tabindex="0"><thead><tr><th>等級</th><th>已知格</th><th>說明</th></tr></thead><tbody><tr><td>簡單</td><td>45</td><td>適合初學者與快速來一局</td></tr><tr><td>中等</td><td>36</td><td>為休閒玩家準備的均衡挑戰</td></tr><tr><td>困難</td><td>31</td><td>需要邏輯推演技巧</td></tr><tr><td>專家</td><td>27</td><td>給想真正接受考驗的老手</td></tr><tr><td>大師</td><td>24</td><td>終極挑戰——只留給最勇敢的人</td></tr></tbody></table><p>每道題目都是獨立生成——絕不會出現兩局相同的題目。</p><h3 id="📱-通用-app" tabindex="-1">📱 <strong>通用 App</strong> <a class="header-anchor" href="#📱-通用-app" aria-label="Permalink to “📱 通用 App”">​</a></h3><p>一次購買，就能在 iPhone、iPad 與 Mac 上使用。各平台都有原生控制方式——iOS 上用手勢觸控，Mac 上用滑鼠與鍵盤。你的進度會透過 iCloud 在所有裝置間同步。</p><p><img src="/screenshot-iphone-main.png" alt="Sudoku 在 iPhone 上"></p><p><img src="/screenshot-mac-difficulty.png" alt="Sudoku 在 Mac 上"></p><h3 id="💡-提示與筆記" tabindex="-1">💡 <strong>提示與筆記</strong> <a class="header-anchor" href="#💡-提示與筆記" aria-label="Permalink to “💡 提示與筆記”">​</a></h3><ul><li><strong>提示</strong>：卡住了嗎？取得提示會揭曉一個正確格子的答案，不會破壞整道題目。</li><li><strong>鉛筆（筆記）</strong>：切換鉛筆模式，就能在空格中記下候選數字。當你填入確定數字時，同一列、同一欄與同一區塊內該數字的鉛筆筆記會自動清除。</li><li><strong>錯誤檢查</strong>：可選擇標示填錯的數字，讓你從錯誤中學習。</li><li><strong>復原</strong>：完整支援復原——任何一步都能隨時收回。</li></ul><h3 id="🏆-每日挑戰" tabindex="-1">🏆 <strong>每日挑戰</strong> <a class="header-anchor" href="#🏆-每日挑戰" aria-label="Permalink to “🏆 每日挑戰”">​</a></h3><p>每天一道全新的大師級題目。累積連續天數，並在「統計資料」的月曆檢視中追蹤你的每日進度。</p><h3 id="📊-統計資料" tabindex="-1">📊 <strong>統計資料</strong> <a class="header-anchor" href="#📊-統計資料" aria-label="Permalink to “📊 統計資料”">​</a></h3><p>追蹤你的表現：總遊戲局數、勝率、目前連續天數、最佳連續天數，以及各難度的細部數據，包括最佳時間與平均時間。透過 iCloud 同步。</p><h3 id="🎨-8-種精緻主題" tabindex="-1">🎨 <strong>8 種精緻主題</strong> <a class="header-anchor" href="#🎨-8-種精緻主題" aria-label="Permalink to “🎨 8 種精緻主題”">​</a></h3><p>用八種手工調製的配色主題個人化你的盤面：經典、午夜、紙張、森林、海洋、日落、薰衣草與玫瑰。每種主題都帶來截然不同的視覺感受，同時維持極佳的可讀性。</p><h3 id="☁️-icloud-同步" tabindex="-1">☁️ <strong>iCloud 同步</strong> <a class="header-anchor" href="#☁️-icloud-同步" aria-label="Permalink to “☁️ iCloud 同步”">​</a></h3><p>你的設定、統計資料、遊戲存檔與每日挑戰進度，會透過 CloudKit 自動同步到所有 Apple 裝置。在 iPhone 上開始一局，在 Mac 上繼續。</p><h3 id="🎮-game-center" tabindex="-1">🎮 <strong>Game Center</strong> <a class="header-anchor" href="#🎮-game-center" aria-label="Permalink to “🎮 Game Center”">​</a></h3><p>在排行榜上以最佳完成時間與其他玩家較勁，並解鎖成就：首次解題、簡單通關、中等通關、困難通關、專家通關、大師通關，以及完美無瑕（不使用提示、不發生錯誤完成）。</p><h3 id="🔇-簡潔純淨-沒有廣告" tabindex="-1">🔇 <strong>簡潔純淨，沒有廣告</strong> <a class="header-anchor" href="#🔇-簡潔純淨-沒有廣告" aria-label="Permalink to “🔇 簡潔純淨，沒有廣告”">​</a></h3><p>沒有中斷、沒有彈出視窗、沒有廣告、沒有 App 內購買。只有純粹專注的解謎樂趣。</p><h3 id="🌍-25-種語言" tabindex="-1">🌍 <strong>25 種語言</strong> <a class="header-anchor" href="#🌍-25-種語言" aria-label="Permalink to “🌍 25 種語言”">​</a></h3><p>可在執行時於「設定」中切換語言，無需重新啟動 App。支援英文、中文（簡體與繁體）、日文、韓文、法文、德文、西班牙文、義大利文、俄文、葡萄牙文、荷蘭文、越南文、泰文、印地文、土耳其文、希臘文、芬蘭文、挪威文、丹麥文、匈牙利文、印尼文、馬來文、烏克蘭文，以及德文（瑞士）。</p><h3 id="🔊-音效" tabindex="-1">🔊 <strong>音效</strong> <a class="header-anchor" href="#🔊-音效" aria-label="Permalink to “🔊 音效”">​</a></h3><p>填入數字、提示、錯誤與勝利都有細緻的音效——可在「設定」中開啟或關閉。</p><h3 id="🖨️-列印題目" tabindex="-1">🖨️ <strong>列印題目</strong> <a class="header-anchor" href="#🖨️-列印題目" aria-label="Permalink to “🖨️ 列印題目”">​</a></h3><p>直接在 Mac 版 App 中列印題目，可選擇難度，並可選擇附上答案。最適合用紙筆離線解題。</p><h2 id="系統需求" tabindex="-1">系統需求 <a class="header-anchor" href="#系統需求" aria-label="Permalink to “系統需求”">​</a></h2><ul><li><strong>iPhone/iPad</strong>：iOS/iPadOS 16.0 或以上版本</li><li><strong>Mac</strong>：macOS 15.0（Sequoia）或以上版本（Apple Silicon）</li><li><strong>儲存空間</strong>：約 50 MB</li></ul><h2 id="隱私" tabindex="-1">隱私 <a class="header-anchor" href="#隱私" aria-label="Permalink to “隱私”">​</a></h2><p>Sudoku 的核心玩法以離線優先為設計原則。所有遊戲資料都儲存在本機，且僅同步到你的個人 iCloud 帳號。沒有廣告、沒有分析工具、沒有第三方追蹤。唯一的網路功能是 iCloud 同步、Game Center，以及「設定」中選用的「更多 App」區塊。</p><p>詳情請參閱<a href="/zh-TW/guide/privacy.html">隱私權政策</a>。</p><h2 id="開始使用" tabindex="-1">開始使用 <a class="header-anchor" href="#開始使用" aria-label="Permalink to “開始使用”">​</a></h2><p>如果你是第一次接觸數獨，請先閱讀<a href="/zh-TW/guide/installation.html">安裝指南</a>，把 App 裝到你的裝置上。</p>`,43)]])}var s=e(a,[[`render`,o]]);export{i as __pageData,s as default};